import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100TopEnergyTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static List<CardInstance> window(ServerMatch m,int count){var deck=m.privateView(A).deck();return List.copyOf(deck.subList(Math.max(0,deck.size()-count),deck.size()));}
    static boolean basic(ServerMatch m,CardInstance c){return m.cardDefinition(c.definitionId()).basicEnergy();}
    static ServerMatch game(int n,boolean special){for(int seed=0;seed<400;seed++){var m=StarterDeck100PokemonTest.gameSeed(n,1,seed,"sm1_en_136","sd100_cn_psychic_energy");if(n==106)StarterDeck100PokemonTest.charge(m,0);var top=window(m,n==106?6:2);if(top.stream().filter(c->basic(m,c)).count()>=(special?1:2)&&(!special||top.stream().anyMatch(c->c.definitionId().equals("sm1_en_136"))))return m;}throw new AssertionError("No top Energy fixture");}
    public static void main(String[] args){for(int n:List.of(106,177)){resolve(n,false,false);resolve(n,true,false);resolve(n,false,true);shortDeck(n);}brainwave();malformed();System.out.println("StarterDeck100TopEnergyTest passed: private top windows, Basic-only any-host distribution, zero selection, precise remainder, protection, short deck and Psychic-unit damage");}
    static void start(ServerMatch m,int n){if(n==106)m.attack(A,"element-chain");else StarterDeck100PokemonTest.ability(m,m.activePokemonView(A).pokemonId());}
    static void resolve(int n,boolean decline,boolean protectedHost){var m=game(n,decline);UUID active=m.activePokemonView(A).pokemonId(),bench=m.benchPokemonView(A).getFirst().pokemonId();if(protectedHost)StarterDeck100CounterMoveTest.shield(m,A,bench,n==106?"ATTACK":"ABILITY");var deck=m.privateView(A).deck();var top=window(m,n==106?6:2);int hand=m.privateView(A).hand().size(),rng=m.randomTranscript().size();start(m,n);var p=m.effectCardPrompt(A);check(new HashSet<>(p.inspectedCards()).equals(new HashSet<>(top)),"look window was filtered too early or wrong size");var expected=top.stream().filter(c->basic(m,c)).toList();check(new HashSet<>(p.candidates()).equals(new HashSet<>(expected)),"non-Basic or outside-window cards offered");var outsider=deck.stream().filter(c->!top.contains(c)&&basic(m,c)).findFirst().orElseThrow();TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(outsider.instanceId())));TopDeckLookTest.rejects(()->m.effectCardPrompt(B));
        var session=MatchSession.multiplayer(m,A,B);String other=new com.google.gson.Gson().toJson(session.view(B,B));for(var card:top)check(!other.contains(card.instanceId().toString()),"private top card leaked to opponent");
        var selected=decline?List.<CardInstance>of():expected.subList(0,2);m.submitEffectCards(A,p.resolutionId(),p.step(),selected.stream().map(CardInstance::instanceId).toList());
        if(!selected.isEmpty()){var d=m.effectAttachmentPrompt(A);TopDeckLookTest.rejects(()->m.confirmEffectEnergyDistribution(A,d.resolutionId(),d.step()));m.assignEffectEnergyDistribution(A,d.resolutionId(),d.step(),selected.getFirst().instanceId(),active);m.assignEffectEnergyDistribution(A,d.resolutionId(),d.step(),selected.getLast().instanceId(),bench);m.confirmEffectEnergyDistribution(A,d.resolutionId(),d.step());}
        var attached=decline?List.<CardInstance>of():protectedHost?List.of(selected.getFirst()):List.copyOf(selected);for(var card:attached)check(StarterDeck100PokemonTest.view(m,A,card.equals(selected.getFirst())?active:bench).attachedEnergyIds().contains(card.instanceId()),"assigned Energy missing");
        if(n==177){var rest=top.stream().filter(c->!attached.contains(c)).toList();check(m.privateView(A).hand().containsAll(rest)&&m.privateView(A).hand().size()==hand+rest.size(),"Arcana remaining cards not all put into hand");check(m.privateView(A).deck().equals(deck.subList(0,deck.size()-top.size()))&&m.randomTranscript().size()==rng,"Arcana shuffled or moved cards outside window");TopDeckLookTest.rejects(()->StarterDeck100PokemonTest.ability(m,active));}
        else {check(m.privateView(A).deck().size()==deck.size()-attached.size()&&m.privateView(A).deck().containsAll(top.stream().filter(c->!attached.contains(c)).toList())&&m.privateView(A).hand().size()==hand,"Element Chain did not leave all unassigned cards in deck");check(m.randomTranscript().size()-rng==m.privateView(A).deck().size()-1,"Element Chain did not shuffle exactly once");}
        TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));
    }
    static void shortDeck(int n){for(int left:List.of(0,1)){var m=game(n,false);m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-left);int hand=m.privateView(A).hand().size();if(n==177&&left==0){TopDeckLookTest.rejects(()->start(m,n));continue;}start(m,n);if(left>0){var p=m.effectCardPrompt(A);check(p.inspectedCards().size()==left,"short look exceeded deck");m.submitEffectCards(A,p.resolutionId(),p.step(),List.of());}check(!m.hasPendingCardSelection()&&m.privateView(A).deck().size()==(n==177?0:left),"short/empty deck stalled");if(n==177)check(m.privateView(A).hand().size()==hand+left,"short Arcana hand count");}}
    static void brainwave(){var m=game(177,false);for(int i=0;i<2;i++)StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_psychic_energy",m.activePokemonView(A).pokemonId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==120,"Brainwave must be60+30 per Psychic Energy unit");}
    static void malformed(){var e=new EffectDefinition("attach_energy",EffectTarget.SELECT_OWN_POKEMON,Map.of("source","HAND","amount","2","minimum","0","top_count","2","remainder","HAND","basic_energy_only","true","target_scope","OWN_FIELD","distribution","ANY"),List.of(),List.of());TopDeckLookTest.rejects(()->AttachEnergyEffect.from(e));}
}
